(() => {
  const view = document.getElementById('view-globe');
  const mount = document.getElementById('globe');
  const countries = document.getElementById('countries');
  const filters = document.getElementById('app-filter');
  const tip = document.getElementById('globe-tip');
  const legend = view.querySelector('.globe-legend');
  const wrap = mount.parentElement;
  const shared = window.Outbound;

  if (!document.querySelector('link[href$="globe.css"]')) {
    const stylesheet = document.createElement('link');
    stylesheet.rel = 'stylesheet';
    stylesheet.href = '/globe.css';
    document.head.append(stylesheet);
  }

  const reducedMotion = matchMedia('(prefers-reduced-motion: reduce)');
  const regionNames = shared?.util?.countryName ? null : new Intl.DisplayNames(['en'], { type: 'region' });
  // Natural Earth 1:110m country polygons, rasterized to a grayscale equirectangular land mask.
  const LAND_TEXTURE = 'data:image/png;base64,';
  const palette = [
    ['#ffffff', '#a0a0a0'],
    ['#d6d6d6', '#787878'],
    ['#eeeeee', '#8a8a8a'],
  ];
  const trackerColor = getComputedStyle(document.documentElement).getPropertyValue('--tracker').trim() || '#ff3b3b';
  // The matching offline sprite is bundled in globe.css.
  const flagCodes = `
    AD AE AF AG AI AL AM AN AO AR AS AT AU AW AX AZ
    BA BB BD BE BF BG BH BI BJ BM BN BO BR BS BT BV
    BW BY BZ CA CC CD CF CG CH CI CK CL CM CN CO CR
    CS CU CV CX CY CZ DE DJ DK DM DO DZ EC EE EG EH
    ER ES ET FI FJ FK FM FO FR GA GB GD GE GF GG GH
    GI GL GM GN GP GQ GR GS GT GU GW GY HK HM HN HR
    HT HU ID IE IL IN IO IQ IR IS IT JM JO JP KE KG
    KH KI KM KN KP KR KW KY KZ LA LB LC LI LK LR LS
    LT LU LV LY MA MC MD ME MG MH MK ML MM MN MO MP
    MQ MR MS MT MU MV MW MX MY MZ NA NC NE NF NG NI
    NL NO NP NR NU NZ OM PA PE PF PG PH PK PL PM PN
    PR PS PT PW PY QA RE RO RS RU RW SA SB SC SD SE
    SG SH SI SJ SK SL SM SN SO SR SS ST SV SX SY SZ
    TC TD TF TG TH TJ TK TL TM TN TO TR TT TV TW TZ
    UA UG UM US UY UZ VA VC VE VG VI VN VU WF WS YE
    YT ZA ZM ZW
  `.trim().split(/\s+/);
  const countryRows = new Map();
  const countryTargets = new Map();
  const expandedCountries = new Set();
  let countryColors = new Map();
  const appButtons = new Map();
  const arcCache = new Map();
  let globe;
  let initFailed = false;
  let state;
  let knownDestinations = new Set();
  let arrivingDestinations = new Set();
  let mapPoints = [];
  let estimateMarkers = new Map();
  let estimateLayoutFrame = 0;
  let headquartersFor;
  let showHeadquarters = false;
  let recentTrail = new Map();
  const trailTime = new Intl.DateTimeFormat('en-GB', {
    hour: '2-digit', minute: '2-digit', second: '2-digit', hourCycle: 'h23',
  });
  let selectedApp = null;
  let modelKey = '';
  let visible = false;
  let rotating = !reducedMotion.matches;
  let pinnedPoint = null;
  let shownPoint = null;
  let tipContentKey = '';

  const overview = node('div', 'globe-overview');
  const heading = node('h2', '', 'Connection map');
  const summary = node('p', '', 'Waiting for network activity…');
  overview.append(heading, summary);
  const motion = node('button', 'globe-motion');
  motion.type = 'button';
  motion.addEventListener('click', () => setRotation(!rotating));
  const hqToggle = node('button', 'globe-hq-toggle', 'Company HQ links');
  hqToggle.type = 'button';
  hqToggle.setAttribute('aria-pressed', 'false');
  hqToggle.title = 'Show headquarters of reported network owners';
  hqToggle.addEventListener('click', async () => {
    if (!headquartersFor) {
      hqToggle.disabled = true;
      try {
        ({ headquartersFor } = await import('/globe-hq.js'));
      } catch (error) {
        console.warn('Could not load Globe headquarters.', error);
        return;
      } finally {
        hqToggle.disabled = false;
      }
    }
    showHeadquarters = !showHeadquarters;
    hqToggle.setAttribute('aria-pressed', String(showHeadquarters));
    hqLegend.hidden = !showHeadquarters;
    clearPoint();
    modelKey = '';
    render();
  });
  wrap.append(overview, motion, hqToggle);
  const trail = node('section', 'globe-trail');
  const trailList = node('ol');
  const trailEmpty = node('p', '', 'Waiting for new destinations…');
  trail.append(node('h3', '', 'Data trail'), trailList, trailEmpty);
  wrap.append(trail);

  const legendLabels = ['Outbound route', 'Return route', 'Tracker / analytics'];
  [...legend.children].forEach((row, i) => {
    row.childNodes.forEach((child) => {
      if (child.nodeType === Node.TEXT_NODE) child.remove();
    });
    row.append(document.createTextNode(legendLabels[i]));
  });
  legend.append(node('p', '', 'Motion illustrates active TCP connections.'));
  const legendDisclosure = node('details', 'globe-legend-disclosure');
  legendDisclosure.append(node('summary', '', 'Map legend'), legend);
  wrap.append(legendDisclosure);
  const estimateLegend = node('div');
  estimateLegend.append(node('span', 'globe-estimate-key'), document.createTextNode('Country-level estimate'));
  legend.insertBefore(estimateLegend, legend.lastElementChild);
  const hqLegend = node('div');
  hqLegend.append(node('span', 'globe-hq-key'), document.createTextNode('Network owner headquarters'));
  hqLegend.hidden = true;
  legend.insertBefore(hqLegend, legend.lastElementChild);
  tip.hidden = true;
  const countryNote = node('p', 'globe-card-note', 'Estimated server locations, including recently closed connections.');
  countries.before(countryNote);
  const countryEmpty = node('p', 'globe-card-note', 'Waiting for destinations…');
  const filterEmpty = node('p', 'globe-card-note', 'Apps appear after connecting to a remote server.');
  countries.after(countryEmpty);
  filters.after(filterEmpty);
  setRotation(rotating);

  function node(tag, className = '', text = '') {
    const element = document.createElement(tag);
    if (className) element.className = className;
    if (text) element.textContent = text;
    return element;
  }

  function hash(text) {
    let value = 0;
    for (const char of text) value = (Math.imul(31, value) + char.codePointAt(0)) >>> 0;
    return value;
  }

  function countryName(code) {
    if (shared?.util?.countryName) return shared.util.countryName(code);
    return code ? regionNames.of(code) : 'Unknown country';
  }

  function hasCoordinates(place) {
    return Number.isFinite(place?.lat) && Math.abs(place.lat) <= 90
      && Number.isFinite(place?.lng) && Math.abs(place.lng) <= 180;
  }

  function plotLocation(place) {
    if (!hasCoordinates(place) || !place.country) return place;
    const usCentroid = place.country === 'US'
      && Math.abs(place.lat - 37.751) < 0.015 && Math.abs(place.lng + 97.822) < 0.015;
    if (place.city?.trim() && !usCentroid) return place;
    const lat = usCentroid ? 37.751 : place.lat;
    const lng = usCentroid ? -97.822 : place.lng;
    return { ...place, city: '', lat, lng, approximate: true };
  }

  function alignCountryEstimates(places) {
    const anchors = new Map();
    for (const place of places) {
      if (!place.approximate) continue;
      if (!anchors.has(place.country)) anchors.set(place.country, { lat: place.lat, lng: place.lng });
      Object.assign(place, anchors.get(place.country));
    }
  }

  function updateTrail(apps) {
    const recent = new Map(recentTrail);
    for (const app of apps) {
      for (const destination of app.destinations) {
        if (!Number.isFinite(destination.firstSeen)) continue;
        const key = JSON.stringify([app.id, destination.ip, destination.firstSeen]);
        const location = plotLocation({ ...destination, country: countryCode(destination.country) });
        recent.set(key, [
          destination.firstSeen, shared?.util?.appLabel?.(app.name) || app.name,
          destination.org || 'Unknown owner',
          location.city?.trim()
            ? [location.city.trim(), location.country].filter(Boolean).join(', ')
            : (location.country ? location.country + ' ~' : 'Unknown'),
        ]);
      }
    }
    recentTrail = new Map([...recent].sort((a, b) => b[1][0] - a[1][0] || a[0].localeCompare(b[0])).slice(0, 6));
  }

  function renderTrail() {
    const model = JSON.stringify([...recentTrail.values()]);
    if (trailList.dataset.model === model) return;
    trailList.dataset.model = model;
    trailEmpty.hidden = recentTrail.size > 0;
    trailList.replaceChildren(...[...recentTrail.values()].map(([at, app, org, location]) => {
      const row = node('li');
      const when = node('time', '', trailTime.format(at));
      when.dateTime = new Date(at).toISOString();
      row.append(when);
      for (const value of [app, org, location]) {
        const cell = node('span', '', value);
        cell.title = value;
        row.append(cell);
      }
      return row;
    }));
  }

  function countryCode(code) {
    return /^[A-Z]{2}$/.test(code) ? code : '';
  }

  function countryFlag(code) {
    const index = flagCodes.indexOf(code);
    if (index < 0) return node('span', 'globe-flag', code || '—');
    const icon = node('span', 'globe-flag globe-flag-icon');
    const x = -(index % 16) * 16;
    const y = -Math.floor(index / 16) * 12;
    icon.style.backgroundPosition = x + 'px ' + y + 'px';
    return icon;
  }

  function plural(count, word) {
    return count === 1 ? word : word + 's';
  }

  function arcColor(hex, active) {
    const rgb = hex.slice(1).match(/../g).map((channel) => parseInt(channel, 16));
    return 'rgba(' + rgb.join(',') + ',' + (active ? 0.88 : 0.3) + ')';
  }

  function reconcile(container, cache, items, key, create, update) {
    const remaining = new Set(cache.keys());
    let next = container.firstElementChild;
    for (const item of items) {
      const id = key(item);
      let element = cache.get(id);
      if (!element) {
        element = create(item);
        cache.set(id, element);
      }
      update(element, item);
      if (element !== next) container.insertBefore(element, next);
      next = element.nextElementSibling;
      remaining.delete(id);
    }
    for (const id of remaining) {
      cache.get(id).remove();
      cache.delete(id);
    }
  }

  function setText(element, text) {
    if (element.textContent !== text) element.textContent = text;
  }

  function renderFilters(apps) {
    const choices = [{ id: '', name: 'All apps' }, ...apps];
    reconcile(filters, appButtons, choices, (app) => app.id, (app) => {
      const button = node('button', 'globe-app');
      button.type = 'button';
      if (app.id) {
        const [out] = palette[hash(app.id) % palette.length];
        button.style.setProperty('--route-out', out);
        button.title = app.id;
      }
      button.addEventListener('click', () => {
        selectedApp = app.id || null;
        setRotation(false);
        clearPoint();
        render();
      });
      return button;
    }, (button, app) => {
      setText(button, app.name);
      const pressed = String((selectedApp || '') === app.id);
      if (button.getAttribute('aria-pressed') !== pressed) button.setAttribute('aria-pressed', pressed);
    });
    filterEmpty.hidden = apps.length > 0;
  }

  function renderCountries(places) {
    const totals = new Map();
    countryTargets.clear();
    for (const place of places) {
      const code = place.country;
      if (!totals.has(code)) totals.set(code, []);
      totals.get(code).push(place);
      const best = countryTargets.get(code);
      if (globe && code && hasCoordinates(place) && (!best || place.sockets > best.sockets)) {
        countryTargets.set(code, place);
      }
    }
    const rows = [...totals].sort(([a, aCount], [b, bCount]) =>
      Number(!a) - Number(!b) || bCount.length - aCount.length || countryName(a).localeCompare(countryName(b)));
    reconcile(countries, countryRows, rows, ([code]) => code, ([code]) => {
      const row = node('li', 'globe-country');
      const button = node('button', 'globe-country-button');
      button.type = 'button';
      const details = node('ul', 'globe-country-companies');
      details.id = 'globe-country-' + (code || 'unknown');
      button.setAttribute('aria-controls', details.id);
      button.addEventListener('click', () => {
        if (expandedCountries.has(code)) {
          expandedCountries.delete(code);
        } else {
          expandedCountries.add(code);
          if (countryTargets.has(code)) focusCountry(code);
        }
        modelKey = '';
        render();
      });
      const icon = countryFlag(code);
      icon.setAttribute('aria-hidden', 'true');
      button.append(icon, node('span', 'globe-country-name', countryName(code)),
        node('span', 'globe-count'));
      row.append(button, details);
      return row;
    }, (row, [code, destinations]) => {
      const button = row.firstElementChild;
      const details = row.lastElementChild;
      const expanded = expandedCountries.has(code);
      setText(button.lastElementChild, String(destinations.length));
      button.setAttribute('aria-expanded', String(expanded));
      details.hidden = !expanded;
      if (expanded) renderCountryCompanies(details, destinations);
    });
    countryEmpty.hidden = rows.length > 0;
  }

  function renderCountryCompanies(list, destinations) {
    const companies = new Map();
    for (const destination of destinations) {
      if (!companies.has(destination.org)) companies.set(destination.org, { sockets: 0, apps: new Set() });
      const company = companies.get(destination.org);
      if (destination.active) company.sockets += destination.sockets;
      company.apps.add(destination.appName);
    }
    const rows = [...companies].sort(([a, first], [b, second]) =>
      second.sockets - first.sockets || a.localeCompare(b))
      .map(([name, { sockets, apps }]) => [name, sockets, [...apps].sort().join(' · ')]);
    const key = JSON.stringify(rows);
    if (list.dataset.model === key) return;
    list.dataset.model = key;
    list.replaceChildren(...rows.map(([name, sockets, apps]) => {
      const row = node('li');
      row.append(node('strong', '', name), node('span', '', sockets + ' live ' + plural(sockets, 'socket')),
        node('small', '', apps));
      return row;
    }));
  }

  function routeAltitude(start, end, scale, endpointAltitude, maximum) {
    const radians = Math.PI / 180;
    const latitude = (end.lat - start.lat) * radians;
    const longitude = (end.lng - start.lng) * radians;
    const haversine = Math.sin(latitude / 2) ** 2
      + Math.cos(start.lat * radians) * Math.cos(end.lat * radians) * Math.sin(longitude / 2) ** 2;
    const halfAngle = Math.asin(Math.sqrt(Math.min(1, Math.max(0, haversine))));
    return Math.min(maximum, halfAngle * scale + endpointAltitude);
  }

  function makeArcs(places, home) {
    const next = new Map();
    for (const place of places) {
      const [out, inbound] = place.tracker ? [trackerColor, trackerColor] : palette[hash(place.appId) % palette.length];
      const spread = hash(place.id) % 10 / 100;
      for (const [direction, start, end, color, scale] of [
        ['out', home, place, out, 0.32],
        ['in', place, home, inbound, 0.22],
      ]) {
        const id = place.approximate
          ? ['estimate', place.country, place.appId, Boolean(place.tracker), Boolean(place.active), direction].join('|')
          : place.id + direction;
        if (next.has(id)) continue;
        const arc = arcCache.get(id) || {};
        Object.assign(arc, {
          startLat: start.lat, startLng: start.lng, endLat: end.lat, endLng: end.lng,
          startAlt: 0.004, endAlt: 0.004,
          altitude: routeAltitude(start, end, scale + spread, 0.004, direction === 'in' ? 0.22 : 0.26),
          color: arcColor(color, place.active),
          active: place.active, inbound: direction === 'in', duration: 3400 + hash(id) % 1200, phase: spread,
        });
        next.set(id, arc);
      }
      if (!showHeadquarters) continue;
      for (const hq of headquartersFor(place.org)) {
        const id = 'hq|' + place.lat + '|' + place.lng + '|' + hq.owner + '|' + hq.city;
        if (next.has(id)) continue;
        const arc = arcCache.get(id) || {};
        Object.assign(arc, {
          startLat: place.lat, startLng: place.lng, endLat: hq.lat, endLng: hq.lng,
          startAlt: 0.012, endAlt: 0.012, altitude: routeAltitude(place, hq, 0.16, 0.012, 0.24),
          color: '#bcbcbc', phase: 0,
          hqLabel: 'owned by ' + hq.owner + ' (HQ: ' + hq.city + ')',
        });
        next.set(id, arc);
      }
    }
    arcCache.clear();
    for (const [id, arc] of next) arcCache.set(id, arc);
    return [...next.values()];
  }

  function updateCountryCells(places) {
    const colors = new Map();
    for (const { country, tracker } of places) {
      if (country) colors.set(country, tracker || colors.get(country) || false);
    }
    if (colors.size === countryColors.size
      && [...colors].every(([code, tracker]) => countryColors.get(code) === tracker)) return;
    countryColors = colors;
    globe.hexPolygonColor((country) => countryCellColor(country));
  }

  function countryCellColor(country) {
    if (countryColors.get(country.code)) return arcColor(trackerColor, true);
    return countryColors.has(country.code) ? 'rgba(235,235,235,0.74)' : 'rgba(195,195,195,0.35)';
  }

  async function loadCountryCells() {
    try {
      const response = await fetch('/data/countries.geojson');
      if (!response.ok) throw new Error('HTTP ' + response.status);
      const { features } = await response.json();
      const countryGeometry = features.map(({ geometry, properties }) => ({
        geometry,
        code: countryCode(properties.ISO_A2) || countryCode(properties.WB_A2)
          || (properties.ADM0_A3 === 'NOR' ? 'NO' : ''),
      }));
      globe.hexPolygonsData(countryGeometry);
    } catch (error) {
      console.warn('Could not load Globe country cells.', error);
    }
  }

  function makePoints(places, home) {
    const points = new Map();
    for (const place of places) {
      const key = place.approximate ? 'estimate|' + place.country : place.lat + '|' + place.lng;
      if (!points.has(key)) {
        points.set(key, { key, lat: place.lat, lng: place.lng, approximate: place.approximate, places: [], sockets: 0 });
      }
      const point = points.get(key);
      point.places.push(place);
      if (place.active) point.sockets += place.sockets;
    }
    return [
      ...points.values(),
      { key: 'home', lat: home.lat, lng: home.lng, label: home.label || 'This PC' },
    ];
  }

  function estimateMarker(entry) {
    const marker = node('button', 'globe-estimate-marker');
    marker.type = 'button';
    marker.append(node('span', 'globe-estimate-count'));
    entry.marker = marker;
    styleEstimateMarker(entry);
    scheduleEstimateLayout();
    marker.addEventListener('pointerenter', () => { if (pinnedPoint === null) renderPoint(entry.point); });
    marker.addEventListener('pointerleave', () => { if (pinnedPoint === null) renderPoint(null); });
    marker.addEventListener('click', () => pinPoint(entry.point));
    return marker;
  }

  function styleEstimateMarker({ marker, point }) {
    const count = point.places.length;
    marker.setAttribute('aria-label', countryName(point.places[0].country) + ' · ' + count + ' country-level estimates');
    marker.style.setProperty('--estimate-size', Math.round(18 + 10 * Math.log1p(count)) + 'px');
    setText(marker.firstElementChild, count + ' approx.');
  }

  function updateEstimateMarkers(points) {
    const next = new Map();
    for (const point of points) {
      if (!point.approximate) continue;
      const entry = estimateMarkers.get(point.key) || { key: point.key };
      Object.assign(entry, { lat: point.lat, lng: point.lng, point });
      if (entry.marker) styleEstimateMarker(entry);
      next.set(point.key, entry);
    }
    estimateMarkers = next;
    globe.htmlElementsData([...next.values()]);
    scheduleEstimateLayout();
  }

  function scheduleEstimateLayout() {
    if (estimateLayoutFrame) return;
    estimateLayoutFrame = requestAnimationFrame(() => {
      estimateLayoutFrame = 0;
      if (!visible || !globe || !estimateMarkers.size) return;
      layoutEstimateLabels();
    });
  }

  function layoutEstimateLabels() {
    const camera = globe.camera().position;
    const candidates = [...estimateMarkers.values()].filter((entry) => entry.marker?.isConnected)
      .sort((a, b) => b.point.places.length - a.point.places.length || a.key.localeCompare(b.key));
    const placed = [];
    const visibility = [];
    for (const { lat, lng, marker } of candidates) {
      const label = marker.firstElementChild;
      const point = globe.getCoords(lat, lng, 0.009);
      const dx = camera.x - point.x, dy = camera.y - point.y, dz = camera.z - point.z;
      const facing = (point.x * dx + point.y * dy + point.z * dz)
        / (Math.hypot(point.x, point.y, point.z) * Math.hypot(dx, dy, dz));
      if (facing < 0.2 || !label.offsetWidth) {
        visibility.push([label, false]);
        continue;
      }
      const { x, y } = globe.getScreenCoords(lat, lng, 0.009);
      const halfWidth = label.offsetWidth / 2 + 2;
      const halfHeight = label.offsetHeight / 2 + 2;
      const box = { left: x - halfWidth, right: x + halfWidth, top: y - halfHeight, bottom: y + halfHeight };
      const show = !placed.some((other) => box.left < other.right && box.right > other.left
        && box.top < other.bottom && box.bottom > other.top);
      if (show) placed.push(box);
      visibility.push([label, show]);
    }
    for (const [label, show] of visibility) label.classList.toggle('label-visible', show);
  }

  function pulseDestinations(places) {
    if (!arrivingDestinations.size) return;
    const rings = new Map();
    if (!reducedMotion.matches) {
      for (const place of places) {
        if (!arrivingDestinations.has(place.id)) continue;
        const key = place.lat + '|' + place.lng;
        const color = place.tracker || rings.get(key)?.tracker ? trackerColor : '#ffffff';
        rings.set(key, { lat: place.lat, lng: place.lng, color, tracker: color === trackerColor });
      }
    }
    arrivingDestinations.clear();
    if (rings.size) globe.ringsData([...rings.values()]);
  }

  function renderPoint(point) {
    if (point === shownPoint) return;
    shownPoint = point;
    const pinned = pinnedPoint !== null;
    const details = point?.places || [];
    const topOrgs = point?.approximate ? summarizeEstimateOwners(details) : null;
    const contentKey = JSON.stringify([pinned, point?.key, point?.label, details.length, topOrgs ?? details.map((place) =>
      [place.org, place.asn, place.ip, place.city, place.country, place.appName, place.ports, place.tracker])]);
    if (tipContentKey === contentKey) return;
    tipContentKey = contentKey;
    tip.replaceChildren();
    tip.hidden = !point;
    tip.classList.toggle('pinned', pinned);
    if (!point) return;

    if (pinned) {
      const close = node('button', 'globe-tip-close', '×');
      close.type = 'button';
      close.setAttribute('aria-label', 'Close destination details');
      close.addEventListener('click', clearPoint);
      tip.append(close);
    }
    if (point.key === 'home') {
      tip.append(node('strong', '', point.label), node('p', '', 'Connections originate here.'));
      return;
    }

    if (topOrgs) {
      tip.append(node('strong', '', countryName(details[0].country)),
        node('p', '', details.length + ' destinations · approximate (country only)'));
      const owners = node('dl', 'globe-estimate-owners');
      for (const [name, count] of topOrgs) {
        owners.append(node('dt', '', name), node('dd', '', String(count)));
      }
      tip.append(owners);
      return;
    }

    for (const place of pinned ? details : details.slice(0, 2)) {
      const row = node('div', 'globe-tip-row');
      const title = node('strong', '', place.org);
      if (place.tracker) title.append(node('span', 'globe-tracker', 'Tracker'));
      const location = [place.city, countryName(place.country)].filter(Boolean).join(', ');
      const fields = node('dl', 'globe-tip-fields');
      for (const [label, value] of [
        ['ASN', place.asn ? 'AS' + place.asn : 'Unknown'],
        ['IP', place.ip],
        ['LOCATION', location],
        ['APP', place.appName],
        ['PORTS', place.ports.length ? place.ports.join(', ') : 'Unknown'],
      ]) {
        fields.append(node('dt', '', label), node('dd', '', value));
      }
      row.append(title, fields);
      tip.append(row);
    }
    if (!pinned && details.length > 2) {
      tip.append(node('p', '', 'Select the point to see all ' + details.length + ' entries.'));
    }
  }

  function summarizeEstimateOwners(places) {
    const counts = new Map();
    for (const { org } of places) counts.set(org, (counts.get(org) || 0) + 1);
    return [...counts].sort(([a, first], [b, second]) => second - first || a.localeCompare(b)).slice(0, 5);
  }

  function clearPoint() {
    pinnedPoint = null;
    renderPoint(null);
  }

  function pinPoint(point) {
    setRotation(false);
    pinnedPoint = point.key;
    shownPoint = null;
    renderPoint(point);
  }

  function focusCountry(code) {
    const { lat, lng } = countryTargets.get(code);
    const point = mapPoints.find((entry) => entry.lat === lat && entry.lng === lng);
    if (!point) return;
    globe.pointOfView({ lat, lng, altitude: 1.85 }, reducedMotion.matches ? 0 : 650);
    pinPoint(point);
  }

  function render() {
    if (!visible || !state) return;
    renderTrail();
    const apps = state.apps.filter((app) => app.destinations.length);
    const nameCounts = new Map();
    for (const app of apps) nameCounts.set(app.name, (nameCounts.get(app.name) || 0) + 1);
    const namedApps = apps.map((app) => {
      const label = shared?.util?.appLabel?.(app.name) || app.name;
      return { ...app, name: nameCounts.get(app.name) > 1 ? label + ' · ' + app.id : label };
    }).sort((a, b) => a.name.localeCompare(b.name) || a.id.localeCompare(b.id));
    if (!namedApps.some((app) => app.id === selectedApp)) selectedApp = null;
    const places = namedApps.filter((app) => selectedApp === null || app.id === selectedApp)
      .flatMap((app) => app.destinations.map((destination) => ({
        id: app.id + '|' + destination.ip, appId: app.id, appName: app.name,
        org: destination.org || 'Unknown owner', city: destination.city,
        ip: destination.ip, asn: destination.asn, ports: destination.ports || [],
        country: countryCode(destination.country), lat: destination.lat, lng: destination.lng,
        active: destination.active, sockets: destination.sockets || 0, tracker: destination.tracker,
      }))).map(plotLocation).sort((a, b) => a.id.localeCompare(b.id));
    alignCountryEstimates(places);
    const key = JSON.stringify([namedApps.map(({ id, name }) => [id, name]), selectedApp, state.home, places]);
    if (key === modelKey) return;
    modelKey = key;
    renderFilters(namedApps);
    renderCountries(places);
    const home = state.home;
    const located = hasCoordinates(home) ? places.filter(hasCoordinates) : [];
    if (!initFailed) {
      const count = located.length;
      const unknown = places.length - count;
      const mapped = count + ' mapped ' + plural(count, 'destination');
      setText(summary, places.length ? mapped + (unknown ? ' · ' + unknown + ' unplaced' : '') : 'Waiting for network activity…');
    }
    if (!globe) return;
    updateCountryCells(places);
    const points = hasCoordinates(home) ? makePoints(located, home) : [];
    mapPoints = points;
    if (shownPoint) {
      const updated = points.find((point) => point.key === shownPoint.key);
      if (updated) renderPoint(updated);
      else clearPoint();
    }
    globe.arcsData(makeArcs(located, home)).pointsData(points.filter((point) => !point.approximate));
    updateEstimateMarkers(points);
    pulseDestinations(located);
  }

  function setRotation(enabled) {
    rotating = enabled;
    if (globe) globe.controls().autoRotate = enabled;
    motion.textContent = enabled ? 'Pause rotation' : 'Resume rotation';
  }

  function initGlobe() {
    try {
      globe = new window.Globe(mount, { animateIn: false, rendererConfig: { antialias: true, alpha: true } })
        .globeImageUrl(LAND_TEXTURE)
        .backgroundColor('#080808')
        .showAtmosphere(false)
        .showGraticules(true)
        .hexPolygonGeoJsonGeometry('geometry')
        .hexPolygonResolution(3)
        .hexPolygonMargin(0.3)
        .hexPolygonAltitude(0.002)
        .hexPolygonUseDots(true)
        .hexPolygonsTransitionDuration(0)
        .hexPolygonColor(countryCellColor)
        .arcAltitude('altitude')
        .arcStartAltitude('startAlt')
        .arcEndAltitude('endAlt')
        .arcColor('color')
        .arcCurveResolution(40)
        .arcDashLength((arc) => arc.hqLabel ? 0.018 : arc.active && !reducedMotion.matches ? (arc.inbound ? 0.24 : 0.58) : 1)
        .arcDashGap((arc) => arc.hqLabel ? 0.029 : arc.active && !reducedMotion.matches ? 0.22 : 0)
        .arcLabel((arc) => arc.hqLabel ? node('div', 'globe-hq-label', arc.hqLabel) : '')
        .arcDashInitialGap('phase')
        .arcDashAnimateTime((arc) => arc.active && !reducedMotion.matches ? arc.duration : 0)
        .arcsTransitionDuration(0)
        .pointAltitude((point) => point.key === 'home' ? 0.022 : 0.008)
        .pointRadius((point) => point.key === 'home' ? 0.65 : Math.min(2.1, 0.24 + Math.sqrt(point.sockets) * 0.23))
        .pointColor((point) => {
          if (point.key === 'home') return '#ffffff';
          if (point.places.some((place) => place.tracker)) return trackerColor;
          return point.sockets ? '#e0e0e0' : '#858585';
        })
        .pointResolution(10)
        .onZoom(scheduleEstimateLayout)
        .htmlAltitude(0.009)
        .htmlElement(estimateMarker)
        .htmlTransitionDuration(0)
        .pointsTransitionDuration(0)
        .ringColor('color')
        .ringAltitude(0.014)
        .ringMaxRadius(2.8)
        .ringPropagationSpeed(3)
        .ringRepeatPeriod(0)
        .pointerEventsFilter((object, data) => ['point', 'globe'].includes(object.__globeObjType)
          || (object.__globeObjType === 'arc' && Boolean(data?.hqLabel)))
        .onPointHover((point) => {
          if (pinnedPoint === null) renderPoint(point);
        })
        .onPointClick(pinPoint)
        .onGlobeClick(clearPoint);

      const controls = globe.controls();
      controls.autoRotateSpeed = 0.27;
      controls.enablePan = false;
      controls.minDistance = 125;
      controls.maxDistance = 530;
      setRotation(rotating);
      globe.onGlobeReady(() => {
        const home = hasCoordinates(state?.home) ? state.home : { lat: 43, lng: -81 };
        globe.pointOfView({ lat: home.lat - 9, lng: home.lng, altitude: 1.65 });
      });
      globe.renderer().setPixelRatio(Math.min(window.devicePixelRatio, 1.5));
      loadCountryCells();
    } catch (error) {
      globe = undefined;
      initFailed = true;
      motion.hidden = true;
      setText(summary, 'The 3D map requires WebGL. Destinations are listed alongside it.');
      console.warn('Outbound could not initialize the globe.', error);
    }
  }

  function syncView() {
    const width = mount.clientWidth;
    const height = mount.clientHeight;
    const nextVisible = !view.classList.contains('hidden') && !document.hidden && width > 0 && height > 0;
    if (!nextVisible) {
      if (visible) {
        globe?.pauseAnimation();
        clearPoint();
      }
      visible = false;
      return;
    }
    if (!globe && !initFailed) initGlobe();
    if (globe) {
      if (globe.width() !== width) globe.width(width);
      if (globe.height() !== height) globe.height(height);
      if (!visible) globe.resumeAnimation();
    }
    visible = true;
    render();
    scheduleEstimateLayout();
  }

  function receiveState(snapshot) {
    updateTrail(snapshot.apps);
    const next = new Set(snapshot.apps.flatMap((app) =>
      app.destinations.map((destination) => app.id + '|' + destination.ip)));
    for (const id of next) {
      if (!knownDestinations.has(id)) arrivingDestinations.add(id);
    }
    for (const id of arrivingDestinations) {
      if (!next.has(id)) arrivingDestinations.delete(id);
    }
    knownDestinations = next;
    state = snapshot;
    render();
  }

  mount.addEventListener('pointerdown', () => setRotation(false));
  mount.addEventListener('wheel', () => setRotation(false), { passive: true });
  view.addEventListener('keydown', (event) => {
    if (event.key === 'Escape') clearPoint();
  });
  reducedMotion.addEventListener('change', () => {
    if (reducedMotion.matches) setRotation(false);
    modelKey = '';
    render();
  });
  new ResizeObserver(syncView).observe(mount);
  new MutationObserver(syncView).observe(view, { attributes: true, attributeFilter: ['class', 'hidden'] });
  document.addEventListener('visibilitychange', syncView);

  if (typeof shared?.onState === 'function') {
    shared.onState(receiveState);
  } else {
    const source = new EventSource('/events');
    source.addEventListener('state', (event) => receiveState(JSON.parse(event.data)));
  }
  syncView();
})();
